code.source:
#include <stdio.h>

int main() {
    int fish = 5;

    fish++;
    printf("after fish++ : %d\n", fish);
    fish--;
    printf("after fish-- : %d\n", fish);

    int a = 5;
    int b = a++;
    printf("post: a = %d, b = %d\n", a, b);

    int c = 5;
    int d = ++c;
    printf("pre : c = %d, d = %d\n", c, d);
    return 0;
}

#include <stdio.h>

int main() {
    int rupees = 100;

    rupees += 50;
    rupees -= 30;
    rupees *= 2;
    rupees /= 4;
    rupees %= 7;

    printf("rupees = %d\n", rupees);
    return 0;
}

